import { useState, useEffect, useCallback } from 'react';
import { Smile, Zap, Database, Clock, Home, Brain } from 'lucide-react';
import { useLocation } from 'wouter';
import { Sidebar } from '@/components/sidebar';
import { Header } from '@/components/header';
import { MetricCard } from '@/components/metric-card';
import { VAPlane } from '@/components/va-plane';
import { TimeSeriesChart } from '@/components/time-series-chart';
import { StatisticsPanel } from '@/components/statistics-panel';
import { DebugConsole } from '@/components/debug-console';
import { TrainingProgress } from '@/components/training-progress';
import { useWebSocket } from '@/hooks/use-websocket';
import { useToast } from '@/hooks/use-toast';

export default function Dashboard() {
  const [, setLocation] = useLocation();
  const [refreshRate, setRefreshRate] = useState(500);
  const [timeRange, setTimeRange] = useState(60);
  const [sessionStartTime] = useState(Date.now());
  const [sessionTime, setSessionTime] = useState('00:00');

  const { toast } = useToast();

  const {
    connectionStatus,
    dataFlowStatus,
    currentData,
    dataHistory,
    totalDataPoints,
    clearHistory,
    reconnect,
  } = useWebSocket();

  // Update session timer
  useEffect(() => {
    const interval = setInterval(() => {
      const elapsed = Math.floor((Date.now() - sessionStartTime) / 1000);
      const minutes = Math.floor(elapsed / 60);
      const seconds = elapsed % 60;
      setSessionTime(`${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`);
    }, 1000);

    return () => clearInterval(interval);
  }, [sessionStartTime]);

  const handleExport = useCallback(() => {
    if (dataHistory.length === 0) {
      toast({
        title: 'No Data',
        description: 'No data available to export',
        variant: 'destructive',
      });
      return;
    }

    const csvContent = [
      'timestamp,valence,arousal',
      ...dataHistory.map(p => 
        `${new Date(p.timestamp).toISOString()},${p.valence},${p.arousal}`
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `bci_data_${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);

    toast({
      title: 'Export Successful',
      description: `Exported ${dataHistory.length} data points`,
    });
  }, [dataHistory, toast]);

  const getProgressValues = (value: number) => {
    const percent = ((value + 1) / 2) * 100;
    return {
      progressValue: percent,
      progressOffset: value < 0 ? (50 - percent) * 2 : 0,
    };
  };

  const valenceProgress = currentData ? getProgressValues(currentData.valence) : { progressValue: 50, progressOffset: 0 };
  const arousalProgress = currentData ? getProgressValues(currentData.arousal) : { progressValue: 50, progressOffset: 0 };

  return (
    <div className="min-h-screen flex bg-primary-dark">
      <Sidebar connectionStatus={connectionStatus} dataFlowStatus={dataFlowStatus} />

      <div className="flex-1 overflow-auto">
        {/* Return to Home Button */}
        <div className="p-4 border-b border-gray-700">
          <button
            onClick={() => setLocation('/')}
            className="flex items-center space-x-2 px-4 py-2 bg-gray-800 hover:bg-gray-700 text-white rounded-lg transition-colors"
          >
            <Home size={16} />
            <span>Return to Home</span>
          </button>
        </div>

        <Header
          onExport={handleExport}
          refreshRate={refreshRate}
          onRefreshRateChange={setRefreshRate}
        />

        <main className="p-6">
          {/* Current Metrics Row */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 mb-6 animate-fade-in">
            <MetricCard
              title="Valence"
              value={currentData?.valence.toFixed(2) || '0.00'}
              icon={<Smile size={20} />}
              color="text-accent-cyan"
              subtitle="Range: -1.00 to +1.00"
              showProgress
              progressValue={valenceProgress.progressValue}
              progressOffset={valenceProgress.progressOffset}
            />

            <MetricCard
              title="Arousal"
              value={currentData?.arousal.toFixed(2) || '0.00'}
              icon={<Zap size={20} />}
              color="text-accent-orange"
              subtitle="Range: -1.00 to +1.00"
              showProgress
              progressValue={arousalProgress.progressValue}
              progressOffset={arousalProgress.progressOffset}
            />

            <MetricCard
              title="Consciousness Φ"
              value={currentData?.phi !== undefined ? currentData.phi.toFixed(4) : 'Computing'}
              icon={<Brain size={20} />}
              color="text-purple-400"
              subtitle="IIT Φ Index"
            />

            <MetricCard
              title="Data Points"
              value={totalDataPoints}
              icon={<Database size={20} />}
              color="text-accent-green"
              subtitle="Total received"
            />

            <MetricCard
              title="Session Time"
              value={sessionTime}
              icon={<Clock size={20} />}
              color="text-secondary-light"
              subtitle="Active monitoring"
            />
          </div>

          {/* Main Visualization Row */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6 animate-slide-up">
            <VAPlane
              currentData={currentData}
              dataHistory={dataHistory}
              onClear={clearHistory}
            />

            <TimeSeriesChart
              dataHistory={dataHistory}
              timeRange={timeRange}
              onTimeRangeChange={setTimeRange}
            />
          </div>

          {/* Training Progress */}
          <div className="animate-slide-up mb-6">
            <TrainingProgress />
          </div>

          {/* Statistics and Debug Row */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-slide-up">
            <StatisticsPanel dataHistory={dataHistory} />
            <DebugConsole connectionStatus={connectionStatus} />
          </div>
        </main>
      </div>
    </div>
  );
}

client/src/pages/home.tsx.content:
import { useState, useEffect } from 'react';
import { useLocation } from 'wouter';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/hooks/use-toast';

export default function Home() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [isUploading, setIsUploading] = useState(false);
  const [showDataSelection, setShowDataSelection] = useState(false);
  const [showTrainingInterface, setShowTrainingInterface] = useState(false);
  const [dataFiles, setDataFiles] = useState<string[]>([]);
  const [loadingFiles, setLoadingFiles] = useState(false);
  const [selectedTrainingFiles, setSelectedTrainingFiles] = useState<string[]>([]);
  const [isTraining, setIsTraining] = useState(false);
  const [trainingProgress, setTrainingProgress] = useState(0);
  const [lossHistory, setLossHistory] = useState<Array<{epoch: number, loss: number}>>([]);
  const [currentLoss, setCurrentLoss] = useState<number | null>(null);
  const [trainingEpochs, setTrainingEpochs] = useState(30);
  const [datasetType, setDatasetType] = useState<'set'>('set');
  const [batchSize, setBatchSize] = useState(16);
  const [learningRate, setLearningRate] = useState(0.0001);
  const [windowSize, setWindowSize] = useState(5.0);
  const [overlap, setOverlap] = useState(0.5);

  // IIT Φ 计算状态
  const [showPhiInterface, setShowPhiInterface] = useState(false);
  const [enablePhi, setEnablePhi] = useState(false);
  const [phiMethod, setPhiMethod] = useState<'mock' | 'IIT3.0' | 'IIT4.0_light'>('mock');
  const [phiMaxChannels, setPhiMaxChannels] = useState(8);

  // Fetch available data files for analysis
  const fetchDataFiles = async () => {
    setLoadingFiles(true);
    try {
      const response = await fetch('/api/data-files');
      if (response.ok) {
        const files = await response.json();
        setDataFiles(files);
      } else {
        toast({
          title: 'Error',
          description: 'Failed to load data files',
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to connect to server',
        variant: 'destructive',
      });
    } finally {
      setLoadingFiles(false);
    }
  };

  // Fetch training subjects for model training
  const fetchTrainingSubjects = async () => {
    setLoadingFiles(true);
    try {
      const response = await fetch('/api/training-subjects');
      if (response.ok) {
        const subjects = await response.json();
        setDataFiles(subjects.map((s: any) => s.id)); // Use subject IDs as file list
      } else {
        toast({
          title: 'Error',
          description: 'Failed to load training subjects',
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to connect to server',
        variant: 'destructive',
      });
    } finally {
      setLoadingFiles(false);
    }
  };

  // Load data files when dialog opens
  useEffect(() => {
    if (showDataSelection) {
      fetchDataFiles();
    } else if (showTrainingInterface) {
      fetchTrainingSubjects();
    }
  }, [showDataSelection, showTrainingInterface]);

  // Handle real data analysis
  const handleDataSelection = async (filename: string) => {
    try {
      const response = await fetch('/api/start-analysis', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ filename }),
      });

      if (response.ok) {
        const result = await response.json();
        setShowDataSelection(false);
        setLocation('/dashboard');
        toast({
          title: 'Real Data Analysis Started',
          description: result.message || `Now analyzing real EEG data from ${filename}`,
          duration: 8000,
        });
      } else {
        throw new Error('Failed to start analysis');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to start real data analysis',
        variant: 'destructive',
      });
    }
  };

  const handleModelUpload = async (event: any) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.name.endsWith('.onnx')) {
      toast({
        title: 'Invalid File Type',
        description: 'Please upload an ONNX model file (.onnx)',
        variant: 'destructive',
      });
      return;
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('model', file);

      const response = await fetch('/api/upload-model', {
        method: 'POST',
        body: formData,
      });

      if (response.ok) {
        toast({
          title: 'Model Uploaded',
          description: 'ONNX model has been successfully uploaded and replaced.',
        });
      } else {
        throw new Error('Upload failed');
      }
    } catch (error) {
      toast({
        title: 'Upload Failed',
        description: 'Failed to upload model. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsUploading(false);
    }
  };

  const handleDataUpload = async (event: any) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    setIsUploading(true);
    try {
      const formData = new FormData();
      for (let i = 0; i < files.length; i++) {
        formData.append('data', files[i]);
      }

      const response = await fetch('/api/upload-data', {
        method: 'POST',
        body: formData,
      });

      if (response.ok) {
        toast({
          title: 'Data Uploaded',
          description: `${files.length} data files have been uploaded successfully.`,
        });
      } else {
        throw new Error('Upload failed');
      }
    } catch (error) {
      toast({
        title: 'Upload Failed',
        description: 'Failed to upload data files. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsUploading(false);
    }
  };

  // Handle training
  const handleStartTraining = async () => {
    if (selectedTrainingFiles.length === 0) {
      toast({
        title: 'No Files Selected',
        description: 'Please select at least one data file for training.',
        variant: 'destructive',
      });
      return;
    }

    setIsTraining(true);
    setTrainingProgress(0);
    setLossHistory([]);
    setCurrentLoss(null);

    try {
      const response = await fetch('/api/train-model', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          dataFiles: selectedTrainingFiles,
          epochs: trainingEpochs,
          datasetType: datasetType,
          batchSize: batchSize,
          learningRate: learningRate,
          windowSize: windowSize,
          overlap: overlap,
          computePhi: enablePhi,
          phiMethod: phiMethod,
          phiMaxChannels: phiMaxChannels
        }),
      });

      if (response.ok) {
        const result = await response.json();
        toast({
          title: 'Training Started',
          description: `Model training has begun with ${selectedTrainingFiles.length} data files.`,
        });

        // Monitor training progress
        monitorTrainingProgress();
      } else {
        throw new Error('Training failed to start');
      }
    } catch (error) {
      toast({
        title: 'Training Failed',
        description: 'Failed to start model training. Please try again.',
        variant: 'destructive',
      });
    }
  };

  // Monitor training progress
  const monitorTrainingProgress = () => {
    const interval = setInterval(async () => {
      try {
        const response = await fetch('/api/training-status');
        const status = await response.json();

        setTrainingProgress(status.progress || 0);

        if (status.bestLoss !== null && status.bestLoss !== currentLoss) {
          setCurrentLoss(status.bestLoss);
          const currentEpoch = Math.round((status.progress / 100) * trainingEpochs);
          if (currentEpoch > 0) {
            setLossHistory(prev => {
              const newHistory = [...prev];
              const existingIndex = newHistory.findIndex(item => item.epoch === currentEpoch);
              if (existingIndex >= 0) {
                newHistory[existingIndex] = { epoch: currentEpoch, loss: status.bestLoss };
              } else {
                newHistory.push({ epoch: currentEpoch, loss: status.bestLoss });
              }
              return newHistory.sort((a, b) => a.epoch - b.epoch);
            });
          }
        }

        if (status.completed) {
          clearInterval(interval);
          setIsTraining(false);
          setShowTrainingInterface(false);
          toast({
            title: 'Training Completed',
            description: `New model trained successfully! Final Loss: ${status.bestLoss?.toFixed(4)}`,
          });
        }

